-- The Vortex Pinnacle (map 657): the instance had no spawns at all. Creature and object spawns, their addons, paths and
-- pools from the 5.4.8 data on new guids (creatures 9220000 to 9239999, objects 1055000 to 1059999).
-- Safe to run twice (every block deletes its own range first).

DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` BETWEEN -9239999 AND -9220000;
DELETE FROM `waypoint_data` WHERE `id` BETWEEN 92200000 AND 92399999;
DELETE FROM `creature_formations` WHERE `memberGUID` BETWEEN 9220000 AND 9239999;
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 9220000 AND 9239999;
DELETE FROM `pool_creature` WHERE `guid` BETWEEN 9220000 AND 9239999;
DELETE FROM `pool_gameobject` WHERE `guid` BETWEEN 1055000 AND 1059999;
DELETE FROM `pool_pool` WHERE `pool_id` BETWEEN 322000 AND 323999;
DELETE FROM `pool_template` WHERE `entry` BETWEEN 322000 AND 323999;
DELETE FROM `creature` WHERE `guid` BETWEEN 9220000 AND 9239999;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 1055000 AND 1059999;

